// worker/index.ts
// The Worker entry. It serves the Next.js app exactly as OpenNext builds it, and adds the cron
// timer that runs the dead-man's switch, so one Worker does both jobs.
import { callSchedulerTick, TickFailedError } from "../lib/engine/tick-client";
// The file below is generated by `opennextjs-cloudflare build`, so it may or may not exist yet.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNextWorker from "../.open-next/worker.js";

interface Env {
  /** The Worker itself, so the timer can call the app without leaving Cloudflare. */
  WORKER_SELF_REFERENCE: { fetch(request: Request): Promise<Response> };
  APP_URL: string;
  CRON_SECRET: string;
}

const MAX_ATTEMPTS = 3;

async function runTick(env: Env): Promise<void> {
  for (let attempt = 1; ; attempt++) {
    try {
      const result = await callSchedulerTick({
        appUrl: env.APP_URL,
        cronSecret: env.CRON_SECRET,
        fetchImpl: (url, init) => env.WORKER_SELF_REFERENCE.fetch(new Request(url, init)),
      });
      console.log(
        JSON.stringify({ event: "tick_ok", attempt, skipped: result.skipped ?? false, examined: result.examined ?? null, errors: result.errors ?? null })
      );
      return;
    } catch (err) {
      const retryable = err instanceof TickFailedError ? err.retryable : true;
      console.error(
        JSON.stringify({ event: "tick_failed", attempt, retryable, message: err instanceof Error ? err.message : "unknown" })
      );
      if (!retryable || attempt >= MAX_ATTEMPTS) throw err; // shows as a failed run in Cloudflare
      await new Promise((resolve) => setTimeout(resolve, 5_000 * 2 ** (attempt - 1)));
    }
  }
}

const worker = {
  fetch: openNextWorker.fetch,
  // Awaited, so a failed tick shows up as a failed run in Cloudflare.
  async scheduled(_controller: unknown, env: Env): Promise<void> {
    await runTick(env);
  },
};

export default worker;
